"""Prove the real compiler test rejects a shared parent-ended flag."""
from pathlib import Path
import hashlib
import io
import json
import os
import sys
import time
import unittest
from unittest.mock import patch

ROOT = Path(__file__).resolve().parent
SOURCE = ROOT / 'source'
sys.path[:0] = [str(SOURCE), str(SOURCE / 'tests')]
from otelc import go_context_bundle as context
from test_go_context_integration import GoContextIntegrationTests


def main() -> None:
    """Mutate generated bytes in memory and require the causal-parent assertion."""
    index = json.loads((ROOT / 'source-index.json').read_text())
    original = context._generated
    new = (b'inherited := trace.SpanFromContext(trace.ContextWithSpanContext(context.Background(), last.SpanContext()))\n'
           b'\tsw := &spanWrapper{inherited, nil, &atomic.Bool{}}')
    old = b'sw := &spanWrapper{last, nil, tc.sw.ended}'

    def reverted(inputs: dict[str, bytes], tasks: bool) -> dict[str, bytes]:
        generated = original(inputs, tasks)
        if tasks:
            name = context.TRACE_OUTPUT + 'otel_trace_context.go'
            assert generated[name].count(new) == 1
            generated[name] = generated[name].replace(new, old).replace(b'\t"context"\n', b'', 1)
        return generated

    go = '/Users/sclarke/go/pkg/mod/golang.org/toolchain@v0.0.1-go1.27.3.darwin-arm64/bin/go'
    for key in list(os.environ):
        if key.startswith(('OTEL', 'GH_', 'GITHUB_', 'SONAR_', 'AWS_')):
            del os.environ[key]
    os.environ.update(OTELC_GO=go, GOTOOLCHAIN='local', GOROOT=str(Path(go).parent.parent),
                      PATH=str(Path(go).parent) + os.pathsep + os.environ.get('PATH', ''),
                      GOPATH=str(ROOT / 'python-context-go-path'),
                      GOMODCACHE=str(ROOT / 'python-context-module-cache'),
                      GOCACHE=str(ROOT / 'python-context-build-cache'), GOWORK='off', GOFLAGS='')
    output = io.StringIO()
    started = time.monotonic()
    suite = unittest.TestSuite([GoContextIntegrationTests(
        'test_original_tasks_keep_parent_after_immediate_and_delayed_completion')])
    with patch.object(context, '_generated', side_effect=reverted):
        result = unittest.TextTestRunner(stream=output, verbosity=2).run(suite)
    (ROOT / 'negative-clone.log').write_text(output.getvalue())
    expected = "self.assertEqual(child['Parent'], parent['SpanID'])"
    detected = (result.testsRun == 1 and not result.errors and bool(result.failures)
                and all(expected in detail for _, detail in result.failures))
    changed = [name for name, digest in index['files'].items()
               if hashlib.sha256((SOURCE / name).read_bytes()).hexdigest() != digest]
    receipt = {'head': index['head'], 'mutation': 'restore-shared-parent-ended-flag',
               'in_memory_only': True, 'tests_run': result.testsRun,
               'expected_causal_parent_failures': len(result.failures),
               'errors': len(result.errors), 'detected_at_expected_assertion': detected,
               'source_files': len(index['files']), 'changed': changed,
               'seconds': round(time.monotonic() - started, 3)}
    (ROOT / 'negative-clone.json').write_text(json.dumps(receipt, indent=2) + '\n')
    print(json.dumps(receipt))
    raise SystemExit(0 if detected and not changed else 1)


if __name__ == '__main__':
    main()
